import{_ as e,o,c as a,aa as r}from"./chunks/framework.BAs_AphD.js";const d="/buildary-help-preview/media/cs/tickets/role_mu2.png",m=JSON.parse('{"title":"Kdo co smí v úkolech","description":"","frontmatter":{"title":"Kdo co smí v úkolech","wiki":"cs:tickets:permissions"},"headers":[],"relativePath":"tickets/permissions.md","filePath":"tickets/permissions.md","lastUpdated":1794209661000}'),n={name:"tickets/permissions.md"};function l(i,t,s,v,k,p){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="kdo-co-smi-v-ukolech" tabindex="-1">Kdo co smí v úkolech <a class="header-anchor" href="#kdo-co-smi-v-ukolech" aria-label="Permalink to &quot;Kdo co smí v úkolech&quot;">​</a></h1><p>Co s úkolem smíte, závisí na dvou věcech: na vaší roli v projektovém týmu stavby a na vašem vztahu k úkolu – zda jste ho zadali, máte ho řešit, nebo schvalovat. Pravidla platí stejně na webu i v mobilní aplikaci.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/editace-ukolu">Změnit stav úkolu a odpovědět</a> v Akademii.</p><h2 id="kompetence-role" tabindex="-1">Kompetence role <a class="header-anchor" href="#kompetence-role" aria-label="Permalink to &quot;Kompetence role&quot;">​</a></h2><p>Role členů projektového týmu mají pro úkoly dvě kompetence. Najdete je v <strong>Nastavení stavby</strong> → <strong>Projektový tým</strong> → záložka <strong>Role členů</strong>, když v nabídce kompetenčních okruhů vyberete <strong>Okruhy - Management úkolů</strong>.</p><figure class="shot" style="--w:760px;"><img src="'+d+'" alt="Záložka Role členů s kompetencemi Vidět všechny úkoly a Zadání nového úkolu" loading="lazy"></figure><table tabindex="0"><thead><tr><th>Kompetence</th><th>S kompetencí</th><th>Bez ní</th></tr></thead><tbody><tr><td><strong>Vidět všechny úkoly</strong></td><td>Vidí všechny úkoly stavby, i ty, se kterými nemá nic společného.</td><td>Vidí jen úkoly, které zadal, řeší nebo schvaluje.</td></tr><tr><td><strong>Zadání nového úkolu</strong></td><td>Smí zakládat nové úkoly.</td><td>Tlačítko <strong>Nový úkol</strong> je zašedlé. Úkoly, které řeší nebo schvaluje, ale upravovat může.</td></tr></tbody></table><p>Kompetence nastavujete rolím, ne jednotlivým lidem. Kterou roli člověk má, určíte v poli <strong>Výchozí role v oprávněných osobách</strong> u člena projektového týmu – viz <a href="/buildary-help-preview/diary/projectteam">Projektový tým: firmy a lidé</a>. Role členům přiděluje a kompetence rolí upravuje ten, kdo smí upravovat projektový tým – viz <a href="/buildary-help-preview/diary/userpermissions">Kdo co smí v deníku</a>.</p><p>Kompetence <strong>Vidět všechny úkoly</strong> ovlivňuje i <a href="/buildary-help-preview/tickets/dashboard">Dashboard</a>: graf <strong>Všechny úkoly</strong> vidí jen uživatelé s touto kompetencí.</p><h2 id="prava-podle-vztahu-k-ukolu" tabindex="-1">Práva podle vztahu k úkolu <a class="header-anchor" href="#prava-podle-vztahu-k-ukolu" aria-label="Permalink to &quot;Práva podle vztahu k úkolu&quot;">​</a></h2><p>V detailu úkolu smíte měnit jen to, co odpovídá vašemu vztahu k úkolu. Ostatní údaje vidíte jen pro čtení.</p><table tabindex="0"><thead><tr><th>Co</th><th>Zadavatel (Autor)</th><th>Schvalovatel</th><th>Řešitel</th></tr></thead><tbody><tr><td>Předmět, popis, kategorie, priorita, plánovaný termín</td><td>ano</td><td>ne</td><td>ne</td></tr><tr><td>Stav úkolu (<strong>Schváleno</strong> a <strong>Zamítnuto</strong> jen Schvalovatel)</td><td>ano</td><td>ano</td><td>ano</td></tr><tr><td>Štítky</td><td>ano</td><td>ano</td><td>ano</td></tr><tr><td>Místo ve výkresu a v mapě</td><td>ano</td><td>ano</td><td>ne</td></tr><tr><td>Přílohy úkolu</td><td>ano</td><td>ano</td><td>ne</td></tr><tr><td>Řešitelé a Schvalovatelé</td><td>ano</td><td>ano</td><td>ne</td></tr><tr><td>Vyjádření a diskuze</td><td>ano</td><td>ano</td><td>ano</td></tr><tr><td>Smazat úkol</td><td>ano</td><td>ne</td><td>ne</td></tr></tbody></table><ul><li>Kdo úkol zadal, je u úkolu uveden jako <strong>Autor</strong>.</li><li><strong>Skutečný začátek</strong> a <strong>Skutečný konec</strong> nemění nikdo – doplní je aplikace sama.</li><li>Stav můžete měnit i přetažením kartičky v Kanbanu, pokud k tomu máte právo – viz <a href="/buildary-help-preview/tickets/task_grid#kanban">Seznam úkolů a filtry</a>.</li><li>Volby, ke kterým nemáte právo, jsou zašedlé – například stavy ve výběru <strong>Stav</strong> nebo volby v menu <strong>⋮</strong> v detailu úkolu.</li></ul><h3 id="role-administrator" tabindex="-1">Role Administrátor <a class="header-anchor" href="#role-administrator" aria-label="Permalink to &quot;Role Administrátor&quot;">​</a></h3><p>Uživatel s rolí <strong>Administrátor</strong> smí v úkolech upravovat všechno. Do diskuze se ale zapojí, jen když je u úkolu zároveň Zadavatelem, Řešitelem nebo Schvalovatelem.</p><h2 id="vyjadreni-a-prilohy" tabindex="-1">Vyjádření a přílohy <a class="header-anchor" href="#vyjadreni-a-prilohy" aria-label="Permalink to &quot;Vyjádření a přílohy&quot;">​</a></h2><ul><li>Svůj příspěvek ve vyjádření smí upravit nebo smazat jen jeho autor, a to jen do chvíle, než na něj někdo zareaguje. Smaže-li se reakce, příspěvek se zase odemkne.</li><li>Přílohu smí smazat jen ten, kdo ji nahrál. Obrázkovou přílohu smí v mobilní aplikaci upravit také jen on. Sdílet přílohu může každý, kdo úkol vidí.</li></ul><h2 id="co-k-cemu-potrebujete" tabindex="-1">Co k čemu potřebujete <a class="header-anchor" href="#co-k-cemu-potrebujete" aria-label="Permalink to &quot;Co k čemu potřebujete&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chcete</th><th>Potřebujete</th></tr></thead><tbody><tr><td>Zadat nový úkol</td><td>Kompetenci <strong>Zadání nového úkolu</strong>.</td></tr><tr><td>Vidět všechny úkoly stavby</td><td>Kompetenci <strong>Vidět všechny úkoly</strong>. Bez ní vidíte jen své úkoly.</td></tr><tr><td>Změnit stav úkolu a napsat vyjádření</td><td>Být Řešitelem, Schvalovatelem nebo Zadavatelem úkolu.</td></tr><tr><td>Změnit Řešitele nebo Schvalovatele</td><td>Být Zadavatelem nebo Schvalovatelem úkolu.</td></tr><tr><td>Upravit zadání úkolu nebo ho smazat</td><td>Být Zadavatelem úkolu.</td></tr><tr><td>Upravit kategorie, štítky a pravidla</td><td>Kompetenci <strong>Administrace stavby</strong> – viz <a href="/buildary-help-preview/tickets/rules">Kategorie, štítky a pravidla</a>.</td></tr><tr><td>Zapnout modul na stavbě</td><td>Kompetenci <strong>Administrace stavby</strong> – viz <a href="/buildary-help-preview/tickets/new_project">Zapnout úkoly na stavbě</a>.</td></tr></tbody></table><p>Pro správu stavby, projektového týmu a výkresů platí kompetence popsané v <a href="/buildary-help-preview/diary/userpermissions">Kdo co smí v deníku</a>.</p>',20)])])}const u=e(n,[["render",l]]);export{m as __pageData,u as default};
